  ('standing-toe-taps','semimembranosus','secondary'),
  ('seated-oblique-twist','obliquus_externus','primary'),
  ('seated-oblique-twist','obliquus_internus','primary'),
  ('seated-oblique-twist','quadratus_lumborum','secondary'),
  ('leg-adduction-adductor-magnus-stretch','adductor_magnus','primary'),
